import type { CourseLesson, CourseQuestion } from './course-types';

export const ENGLISH_SOURCE='https://www.gov.uk/government/publications/national-curriculum-in-england-english-programmes-of-study/national-curriculum-in-england-english-programmes-of-study';
export const ENGLISH_ALLOCATION_NOTE='Year 1 and Year 2 follow primary-age foundations. Years 3–4 and 5–6 divide two-year DfE programmes into an editorial sequence; Years 7–9 divide the KS3 programme editorially. This original practice resource needs teacher review, systematic phonics, handwriting, discussion and wider whole-book reading.';
type Kind='phonics'|'spelling'|'noun'|'verb'|'adjective'|'adverb'|'sentence'|'question'|'command'|'exclamation'|'tense'|'conjunction'|'pronoun'|'determiner'|'preposition'|'fronted'|'clause'|'relative'|'modal'|'passive'|'subjunctive'|'apostrophe'|'speech'|'comma'|'semicolon'|'colon'|'hyphen'|'cohesion'|'retrieval'|'inference'|'sequence'|'prediction'|'summary'|'vocabulary'|'comparison'|'figurative'|'poetry'|'persuasion'|'viewpoint'|'formal'|'evidence'|'evaluation'|'structure'|'editing'|'discussion';
type Week={kind:Kind;title:string;p:string};
type Topic={domain:string;idea:string;method:string;caution:string;words:[string,string][];mission:string};
const T=(domain:string,idea:string,method:string,caution:string,words:[string,string][],mission:string):Topic=>({domain,idea,method,caution,words,mission});
const TOPICS:Record<Kind,Topic>={
  phonics:T('Word reading','Letters and letter groups can represent the sounds in spoken words.','Say the taught sounds, then blend them in order. Ask a grown-up to model the sounds rather than letter names.','The activities use selected patterns; they do not replace a systematic phonics programme matched to your learning.',[['sound','A part of a spoken word.'],['blend','Join spoken sounds to read a word.']],'Draw a word trail. Say, blend and write three words with today’s pattern, then read them to a grown-up.'),
  spelling:T('Spelling','Spelling uses sound patterns, word parts and remembered word-specific details.','Look at the root and any prefix or suffix. Say the word, look closely, cover it, write it, then check every letter.','A rule can have exceptions. Practise these examples and use a dictionary or teacher for unfamiliar words.',[['root','The main part of a word before additions.'],['suffix','A word part added at the end.'],['prefix','A word part added at the beginning.']],'Make a mini word museum: write three examples, mark the shared part, and use each in an original sentence.'),
  noun:T('Grammar','A noun can name a person, place, thing or idea; a proper noun names a particular one.','Find the word naming the requested item in the sentence. Capitalise names such as people and places.','More than one noun can occur in a sentence. Follow the question’s specific clue.',[['noun','A word naming a person, place, thing or idea.'],['proper noun','A name for a particular person, place or thing.']],'Draw a scene and label its nouns. Give one character a made-up name with a capital letter.'),
  verb:T('Grammar','Verbs can express actions, events or states, such as jump, happen or be.','Find what is happening or what state is described. Match the verb form to the subject and time.','A verb is not always a visible action: forms of be, have and seem can also be verbs.',[['verb','A word expressing an action, event or state.'],['subject','The person or thing the clause is about.']],'Write a three-action scene and underline the verbs, then explain who performs each action.'),
  adjective:T('Grammar','An adjective adds information about a noun, often describing a quality.','Look for the quality attributed to the person or thing. Test whether it describes the noun in this sentence.','Word classes depend on use: a word can do a different job in another sentence.',[['adjective','A word giving information about a noun.'],['describe','Give details about something.']],'Design a creature or object with three carefully chosen adjectives, then explain how the details change its picture.'),
  adverb:T('Grammar','An adverb can modify a verb, adjective, another adverb or a whole clause.','In these examples, identify the word telling how an action happens. Compare how different choices change the action.','Many manner adverbs end in -ly, but not every adverb does, and not every -ly word is an adverb.',[['adverb','A word that modifies a verb, adjective, adverb or clause.'],['manner','How an action happens.']],'Write the same action three times with different manner adverbs and act or describe the differences.'),
  sentence:T('Grammar and punctuation','A sentence expresses a complete thought and usually contains a main clause.','Read it aloud, check it makes sense, start with a capital and choose an appropriate ending mark.','A full stop alone cannot turn a fragment into a complete sentence.',[['capital','A large-form letter used at starts and in names.'],['sentence','Words expressing a complete thought.']],'Make a three-sentence picture story. Say each sentence before writing and check its beginning and ending.'),
  question:T('Grammar and punctuation','A question asks for information and normally ends with a question mark.','Read the purpose and word order. Choose a question word or form that asks the intended thing.','A statement about a question is not always itself a question.',[['question','Words asking for information.'],['question mark','The ? punctuation used at the end of a direct question.']],'Write three questions for a fictional explorer, each asking a different useful detail.'),
  command:T('Grammar','A command tells someone what to do and commonly uses an imperative verb.','Put the action first, make the instruction clear, and include details the reader needs.','A command can be polite. “Please” changes tone without changing its instructional purpose.',[['command','A sentence telling someone what to do.'],['imperative','A verb form commonly used to give an instruction.']],'Write safe paper-game instructions for a partner, then follow them to find any missing steps.'),
  exclamation:T('Grammar and punctuation','Exclamations can express strong reactions. In the primary grammar pattern, an exclamation sentence begins with what or how.','Look at the whole sentence structure, not only the final exclamation mark.','An exclamation mark can also end a forceful command or statement; punctuation alone does not determine sentence type.',[['exclamation','A sentence such as “What a bright day it is!”'],['reaction','A response to something noticed.']],'Describe an imaginary surprise using a what or how exclamation, then compare it with a plain statement.'),
  tense:T('Grammar','Verb forms help express when an action or state occurs.','Compare present and past forms; use auxiliary verbs where required, such as is running or has finished.','Some past forms are irregular: went is the past of go, not goed.',[['tense','A grammatical way verbs express time.'],['auxiliary','A helping verb used with another verb.']],'Write a diary pair: one sentence about now and one about yesterday, then mark the changed verb forms.'),
  conjunction:T('Grammar','Conjunctions link words or clauses and express relationships such as addition, contrast or reason.','Choose the relationship first: and adds, but contrasts, because gives a reason.','A conjunction must fit both the meaning and the grammar of the linked ideas.',[['conjunction','A word linking words, phrases or clauses.'],['reason','An explanation of why something happens.']],'Join three pairs of story ideas using different conjunctions, then explain why each connection fits.'),
  pronoun:T('Grammar','Pronouns can refer to people or things without repeating their names.','Work out who or what a pronoun refers to. Keep the reference clear when more than one character is present.','Do not guess a real person’s pronouns. These fictional examples state the relevant reference.',[['pronoun','A word such as she, they or it used instead of a noun phrase.'],['reference','Who or what a word points to.']],'Write a short fictional paragraph, replace suitable repeated nouns with clear pronouns, and check every reference.'),
  determiner:T('Grammar','Determiners come before nouns and help specify which thing or how many.','Find words such as a, the, this or some before the noun phrase. Choose a or an by the following sound.','A/an depends on sound, not simply the first written letter.',[['determiner','A word specifying a noun, such as the, some or this.'],['noun phrase','A group centred on a noun.']],'Make a paper catalogue using a, an, the, this and some, then explain how each choice identifies the object.'),
  preposition:T('Grammar','Prepositions express relationships such as place, time or direction and usually introduce a noun phrase.','Look for the relationship: under a bridge, after lunch, through a tunnel.','The whole prepositional phrase adds information; distinguish the preposition from its following noun.',[['preposition','A word such as under or after introducing a relationship.'],['phrase','Words grouped together without a full subject–verb clause.']],'Draw an imaginary map and describe five relationships using precise prepositional phrases.'),
  fronted:T('Grammar and punctuation','A fronted adverbial puts information about time, place or manner before the main clause.','Move the adverbial to the start and normally separate it from the main clause with a comma.','An adverbial can be a word, phrase or clause; it is not always one adverb.',[['adverbial','A word or group giving information such as time, place or manner.'],['fronted','Placed before the main clause.']],'Write a three-event scene, beginning each sentence with a different time or place adverbial.'),
  clause:T('Grammar','A clause typically contains a subject and verb; a subordinate clause depends on a main clause.','Find the main message and then the supporting clause. Use because, although or when to show its relationship.','A subordinate clause beginning “because” is usually incomplete without its main clause.',[['main clause','A clause that can stand as a complete sentence.'],['subordinate clause','A clause dependent on another clause.']],'Build three main-clause and subordinate-clause pairs; move one subordinate clause and check punctuation.'),
  relative:T('Grammar','A relative clause adds information about a noun, often introduced by who, which or that.','Identify the noun being described, then read the added clause and its relative pronoun.','Some clauses identify which noun is meant; others add extra information and are separated by commas.',[['relative clause','A clause giving information about a noun.'],['relative pronoun','A word such as who, which or that introducing many relative clauses.']],'Describe a fictional invention with two relative clauses, deciding whether each detail identifies it or adds extra information.'),
  modal:T('Grammar','Modal verbs express meanings such as possibility, ability, permission or obligation.','Compare might, could, can, should and must in context. Explain how each changes the strength or purpose.','A modal does not prove that an event will happen.',[['modal verb','A verb such as might or must that modifies meaning.'],['possibility','Something that could happen.']],'Write an explorer’s plan with a possibility, an ability and an obligation, then compare the modal choices.'),
  passive:T('Grammar','In the passive voice, the grammatical subject receives the action, such as “The gate was opened by Mina.”','Find a form of be plus a past participle, then identify who receives the action and who performs it.','Passive voice changes the focus; it is not automatically better or worse than active voice.',[['passive','A voice in which the subject receives the action.'],['agent','The performer of an action.']],'Write a pretend news report with one active and one passive version of an event and explain the change of focus.'),
  subjunctive:T('Grammar','Formal requests can use the subjunctive base form, such as “I suggest that she be ready.”','After a formal demand or recommendation, look for the base verb form; “If I were” can express an imagined situation.','These forms belong to particular contexts; ordinary present-tense forms are still correct in other contexts.',[['subjunctive','A verb form used in certain formal or hypothetical constructions.'],['formal','Language chosen for an official or careful context.']],'Write two formal recommendations for a fictional team and one imagined “If I were” sentence.'),
  apostrophe:T('Spelling and punctuation','An apostrophe can mark omitted letters in a contraction or possession.','Expand contractions to see missing letters. For possession, first decide whether the owner noun is singular or plural.','A normal plural does not need an apostrophe. Its position matters in possession.',[['contraction','A shortened form, such as do not becoming don’t.'],['possession','A relationship showing what belongs to whom.']],'Make contraction cards or labels for fictional characters’ belongings, then explain each apostrophe.'),
  speech:T('Punctuation','Direct speech records a speaker’s actual words using inverted commas and suitable punctuation.','Keep the spoken words inside quotation marks; put reporting words outside and separate them appropriately.','A reporting clause is not part of what the character said.',[['direct speech','The exact words spoken by a character.'],['reporting clause','Words identifying the speaker or how they spoke.']],'Write a short conversation between two fictional characters, marking spoken words and reporting clauses.'),
  comma:T('Punctuation','Commas help organise lists and mark certain clause or phrase boundaries.','Read the structure, then place commas between list items or around additional parenthetical information.','Do not join two independent sentences with only a comma.',[['list','A sequence of separate items.'],['parenthesis','Extra information added within a sentence.']],'Write a packing list and a sentence containing an extra detail; mark and explain each comma.'),
  semicolon:T('Punctuation','A semicolon can link closely related independent clauses without a coordinating conjunction.','Check that both sides could stand as complete sentences and that their meanings connect.','A semicolon is not used simply because you want a long pause.',[['semicolon','The ; mark linking related independent clauses or separating complex list items.'],['independent clause','A clause able to stand as a complete sentence.']],'Write two related statements about a fictional event, connect them with a semicolon, and justify the relationship.'),
  colon:T('Punctuation','A colon can introduce an explanation, example or list after a complete introductory clause.','Check that the words before the colon form a complete introduction. Then make the following detail fulfil it.','Do not insert a colon between a verb and its ordinary object.',[['colon','The : mark introducing related detail.'],['introduction','Words preparing the reader for what follows.']],'Write a museum notice with a complete introduction and a colon-led list or explanation.'),
  hyphen:T('Punctuation','A hyphen can link parts of a compound modifier and sometimes prevent ambiguity.','Read which words work together before a noun. Compare meanings with and without the link.','Hyphenation varies by word and context; these activities use clear examples, not an all-purpose rule.',[['hyphen','The short - mark connecting parts of some words or expressions.'],['ambiguity','More than one possible meaning.']],'Create clear labels such as “a well-lit room” and explain how the linked words describe one feature.'),
  cohesion:T('Writing','Cohesion helps sentences and paragraphs connect for the reader.','Use clear references, consistent tense, repeated key ideas and appropriate linking phrases.','A linking phrase must show the actual relationship, not just decorate the text.',[['cohesion','Connections that help a text hold together.'],['link','A relationship connecting ideas.']],'Write a three-sentence explanation, check each pronoun reference and add one meaningful connecting phrase.'),
  retrieval:T('Reading','Retrieval finds information explicitly stated in a text.','Read the question, scan for the named detail and check the exact sentence.','Do not add an invented fact or choose an answer just because it sounds likely.',[['detail','A specific piece of information.'],['retrieve','Find stated information.']],'Create a tiny information card about an imaginary place and write questions answered directly by its details.'),
  inference:T('Reading','An inference combines text clues with sensible reasoning to suggest something unstated.','Choose a clue, explain what it suggests, and use cautious language where the text is not certain.','Several interpretations may be possible; prefer the one best supported by the provided clues.',[['inference','A reasoned idea based on clues.'],['evidence','Details supporting a claim.']],'Write a character feeling without naming the emotion; give two actions that help a reader infer it.'),
  sequence:T('Reading and writing','Sequence places events or instructions in a meaningful order.','Look for what happens first, what follows and what causes the next step.','An earlier event is not automatically the cause of everything that follows.',[['sequence','The order of events or steps.'],['next','The event or step that follows.']],'Draw three event cards, put them in order and retell the story clearly.'),
  prediction:T('Reading','A prediction proposes what may happen next using existing details.','Notice the situation, clues and character aims. Explain why a possible next event fits.','A prediction is a possibility, not a guaranteed fact.',[['predict','Suggest what may happen next.'],['clue','A detail that helps you reason.']],'Write a story opening with two clues, then suggest two possible endings and which has stronger support.'),
  summary:T('Reading and writing','A summary keeps the main information while leaving out smaller details.','Identify the central event or idea and express it concisely in your own words.','A summary should not add a new event or change the original meaning.',[['summary','A short account of the main ideas.'],['main idea','The central message or event.']],'Summarise an original mini story in one sentence, then explain why you omitted one smaller detail.'),
  vocabulary:T('Vocabulary','Context can help explain an unfamiliar word’s meaning.','Read the nearby actions, descriptions and contrasts, then test a possible meaning in the sentence.','A familiar-looking word can have more than one meaning. Use the present context.',[['context','The words and situation surrounding an item.'],['synonym','A word with a similar meaning in a given context.']],'Make three vocabulary cards with a word, a child-friendly meaning and a sentence that supplies a clue.'),
  comparison:T('Reading','Comparison explores similarities and differences between texts or characters.','Use a detail from each text, name the shared feature or contrast, then explain its significance.','Keep both texts in view rather than describing only one.',[['compare','Examine similarities and differences.'],['contrast','A difference between things.']],'Write two short descriptions of the same place from different characters’ views and compare their evidence.'),
  figurative:T('Reading and writing','Figurative language can present an idea through comparison or imaginative description.','Distinguish simile, metaphor and personification, and explain the particular image in context.','Naming a device is only a first step; explain what the choice suggests.',[['simile','A comparison often using like or as.'],['metaphor','A description presenting one thing as another.'],['personification','Giving human qualities to something non-human.']],'Describe an imaginary place with one simile and one personification, then explain the images.'),
  poetry:T('Reading and spoken language','Poetry can shape meaning through sound, rhythm, line breaks and precise images.','Read aloud, notice repeated sounds or patterns, and explain how a choice affects the listener.','Poems do not all rhyme. A rhyme alone does not tell the whole meaning.',[['rhyme','Words with matching end sounds.'],['alliteration','Nearby words beginning with the same consonant sound.']],'Write and perform a short original poem about an imaginary object, trying one sound pattern and explaining its effect.'),
  persuasion:T('Writing and reading','Persuasive language presents reasons intended to influence an audience.','Separate the claim from its supporting evidence. Consider audience, counterarguments and word choices.','An emotional slogan is not evidence that a claim is true.',[['claim','A statement proposed for acceptance.'],['counterargument','A reason supporting a different view.']],'Write a fair proposal for an imaginary club, including a reason, evidence and an answer to a possible objection.'),
  viewpoint:T('Reading','A viewpoint is a perspective shaped by what a speaker knows, values or experiences.','Ask who is speaking, which details they select and what they may not know.','A narrator’s statement is not automatically the author’s belief or an objective fact.',[['viewpoint','A way of seeing or interpreting events.'],['narrator','The voice telling a story.']],'Describe a fictional event from two people’s perspectives, showing how each notices different details.'),
  formal:T('Writing and spoken language','Register is the choice of language suited to audience, purpose and situation.','Compare a friendly note with an official request. Choose precise, respectful wording that suits the reader.','Informal language is not inferior; it may fit a different purpose.',[['register','Language style chosen for a situation.'],['audience','The people a text addresses.']],'Write the same request as a friend’s note and as a formal club letter, then explain the differences.'),
  evidence:T('Reading and discussion','A reasoned interpretation connects a claim to relevant textual evidence.','Select a precise quotation or accurate paraphrase, explain the link, and acknowledge limits.','A quotation is useful only when it supports the stated point.',[['interpretation','A reasoned explanation of meaning.'],['quotation','Words reproduced exactly from a text.']],'Make a claim about an original mini passage, copy one short supporting detail and explain its connection.'),
  evaluation:T('Reading','Evaluation judges an interpretation or source by considering evidence and limitations.','Separate stated facts, opinions and unsupported conclusions. Consider what more you would need to know.','Confidence or popularity alone does not make a source reliable.',[['evaluate','Judge using reasons and evidence.'],['reliable','Trustworthy for a particular claim.']],'Compare two imaginary notices, identify one strong and one weak claim, then say what evidence would help.'),
  structure:T('Writing and reading','Text structure organises information or events for a purpose.','Identify openings, stages, contrasts and endings. Explain what the arrangement helps a reader understand.','A heading or paragraph is useful when its content and purpose are clear.',[['paragraph','A group of sentences developing a related point.'],['structure','The way parts of a text are organised.']],'Plan a story or report with three labelled sections, explain their order, then write one section.'),
  editing:T('Writing','Editing improves meaning, clarity and accuracy; proofreading checks the final details.','Read for meaning first, improve wording and organisation, then check spelling and punctuation.','Changing a word should preserve or deliberately improve the intended meaning.',[['edit','Revise a text to improve it.'],['proofread','Check a text for remaining errors.']],'Write a short original paragraph, make two purposeful improvements, and explain why each helps the reader.'),
  discussion:T('Spoken language','Discussion works when people listen, build on ideas and explain their reasons.','Take turns, restate another idea fairly, and add a supported response or question.','Disagree with an idea respectfully; do not attack the person offering it.',[['discussion','A conversation exploring ideas.'],['justify','Give reasons supporting a point.']],'With a grown-up or imaginary partner, discuss a fictional club decision; give a reason, a listening response and a useful question.'),
};
