      const opening=['After lunch','At the gate','Before sunrise','In the garden','With great care'][seed%5];
      if(mode===0)return c(`Which correctly punctuates a fronted adverbial?`,`${opening}, ${name} ${past} the ${object}.`,[`${opening} ${name}, ${past} the ${object}.`,`${opening} ${name} ${past}, the ${object}.`],'The comma comes after the introductory adverbial.',`${opening} is placed before the main clause and followed by a comma.`);
      if(mode===1)return c(`In “${opening}, ${name} ${past} the ${object}”, which part is fronted?`,opening,[name,`the ${object}`],'The fronted phrase appears before the main clause.',`${opening} supplies introductory time, place or manner information.`);
