      if(mode===2)return c('Which sentence adds non-defining information with commas?',`${name}, who loves drawing, made a card.`,[`${name} who, loves drawing made a card.`,`${name}, who loves, drawing made a card.`],'Put commas around the whole extra clause.','Who loves drawing is additional information about the already named character.');
      if(mode===3)return c('In “The book that has a blue cover is mine”, what does the relative clause help do?','Identify which book is meant',['State that every book is mine','Name a person'],'The clause narrows the choice of books.','That has a blue cover identifies the particular book.');
