      if(mode===0)return c(`Which is a passive version of ${quote(active)}?`,passive,[`The ${object} ${past} ${name}.`,`${name} was ${participle} by the ${object}.`],'Keep the same action and roles but focus on the receiver.',`The ${object} receives the action; ${name} remains the agent.`);
