      if(w.p==='fronted' && mode<=2)return c('Choose punctuation after a fronted adverbial.',`After lunch, ${name} ${past} the ${object}.`,[`After, lunch ${name} ${past} the ${object}.`,`After lunch ${name}, ${past} the ${object}.`],'Put the comma at the end of the whole introductory phrase.','After lunch is the fronted adverbial and is followed by a comma.');
